function EXTRA(R,ICON){
 /* hook: hot and cold jugs into one bucket, and the reverse that never happens */
 ICON.thMix=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:TH_GREY,sw:3,r:18})}
  ${TH_jug(18,22,TH_HOT,'80 °C')}${TH_jug(110,22,TH_COLD,'20 °C')}${TH_arrow(216,66,262,66,TH_DARK,4,16)}
  <path d="M276,40 L356,40 L346,134 L286,134 Z" fill="${TH_WARM}" fill-opacity=".9" stroke="${TH_STEEL}" stroke-width="3"/>${TH_T(316,96,'44 °C',{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${TH_T(54,128,'2 kg',{fs:20,fw:700,a:'middle',fill:TH_GREY})}${TH_T(146,128,'3 kg',{fs:20,fw:700,a:'middle',fill:TH_GREY})}${TH_T(190,160,'mixing: it just happens',{fs:20,fw:700,a:'middle',fill:TH_GREY})}</g>`;
 ICON.thNo=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${TH_box(0,0,380,170,{fill:'#FFFFFF',st:RED,sw:3,r:18})}
  <path d="M24,40 L104,40 L94,134 L34,134 Z" fill="${TH_WARM}" fill-opacity=".9" stroke="${TH_STEEL}" stroke-width="3"/>${TH_T(64,96,'44 °C',{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})}
  ${TH_arrow(118,80,176,80,TH_DARK,4,16)}${TH_L(132,62,162,98,RED,6)}${TH_L(162,62,132,98,RED,6)}
  ${TH_jug(194,30,TH_HOT,'80 °C')}${TH_jug(282,30,TH_COLD,'20 °C')}${TH_T(190,160,'never splits back by itself',{fs:20,fw:700,a:'middle',fill:RED})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.thTsI=(x,y)=>{const sx=s=>30+s/0.75*340,b0=290,ty=T=>b0-T/650*260;const P2=TH_range(0,TH_SP,30).map(s=>[sx(s),ty(TH_air(1.005,s))]);
  const s=`<polygon points="${P2.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')} ${sx(TH_SP)},${b0} ${sx(0)},${b0}" fill="${BLU}" fill-opacity=".22"/>`+TH_ax(30,b0,380,290)+TH_poly(P2,BLU,6)+
   `<circle cx="${sx(0)}" cy="${ty(300)}" r="8" fill="${TH_DARK}"/><circle cx="${sx(TH_SP)}" cy="${ty(600)}" r="8" fill="${TH_DARK}"/>`+TH_T(sx(0)+14,ty(300)-8,'1',{fs:24,fw:800})+TH_T(sx(TH_SP)+14,ty(600)+8,'2',{fs:24,fw:800})+
   TH_T((sx(0)+sx(TH_SP))/2,b0-40,'area = Q',{fs:28,fw:800,a:'middle',fill:BLU});
  return `<g transform="translate(${x-210} ${y-160})">${s}</g>`};
 ICON.thAcct=(x,y)=>{const z=150,k=110;const bars=[['hot',-0.9008,TH_HOT],['cold',0.9889,TH_COLD],['Sgen',0.0882,GRN]];let s=TH_L(0,z,420,z,TH_DARK,3);
  bars.forEach(([n,v,col],i)=>{const x0=20+i*140,h=Math.abs(v)*k;s+=`<rect x="${x0}" y="${v<0?z:z-h}" width="100" height="${Math.max(h,6)}" rx="5" fill="${col}"/>`+
   TH_T(x0+50,v<0?z+h+32:z-h-14,(v>0?'+':'−')+Math.abs(v).toFixed(4),{fs:24,fw:800,a:'middle',fill:TH_DARK})+TH_T(x0+50,v<0?z-14:z+32,n,{fs:22,fw:700,a:'middle',fill:TH_GREY})});
  return `<g transform="translate(${x-210} ${y-150})">${s}</g>`};
 ICON.thNums=(x,y)=>{let s=TH_box(0,0,420,130,{fill:'#E7F5FF',st:BLU,sw:3})+TH_T(210,62,'1.393 kJ/K',{fs:36,fw:800,a:'middle',fill:BLU})+TH_T(210,104,'2 kg air, either route',{fs:22,a:'middle',fill:TH_GREY});
  s+=TH_box(0,170,420,130,{fill:'#EBFBEE',st:GRN,sw:3})+TH_T(210,232,'+0.0882 kJ/K',{fs:36,fw:800,a:'middle',fill:GRN})+TH_T(210,274,'Sgen of mixing water',{fs:22,a:'middle',fill:TH_GREY});
  return `<g transform="translate(${x-210} ${y-150})">${s}</g>`};
}
